exercises.starter_code:
#include <stdio.h>

int main(void) {
    /* const char *host = ...; int port = ...; int debug = 1; */
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    const char *host = "localhost";
    int port = 8080;
    int debug = 1;
    printf("%s %d %s", host, port, debug ? "true" : "false");
    return 0;
}

exercises.starter_code:
#include <stdio.h>

int main(void) {
    int a = 5;
    int b = 10;
    /* swap */
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int a = 5;
    int b = 10;
    int t = a;
    a = b;
    b = t;
    printf("%d %d", a, b);
    return 0;
}
